from itertools import permutations
layers_test={
5:[[5,0,5,0,0,5],[0,5,0,0,0,5],[5,5,5,0,0,0]],
4:[[0,0,0,4,0,4],[0,0,0,0,0,0],[4,0,0,4,0,0]],
2:[[2,0,2,0,2,2],[2,2,0,2,2,2],[2,2,2,2,2,2]],
8:[[0,0,8,8,0,0],[0,8,0,0,8,8],[0,0,0,8,0,0]]}
layers_demo={
5:[[0,5,5,5,5,0],[5,5,0,5,5,5],[5,5,0,5,0,0]],
4:[[0,0,4,0,0,0],[4,0,4,4,4,0],[4,0,0,0,0,0]],
2:[[2,0,2,2,0,2],[2,0,0,0,0,2],[0,0,0,2,0,0]],
8:[[0,8,0,8,0,0],[0,8,0,0,0,0],[0,8,0,8,0,0]]}
def project(L,order):
 return [[next((L[k][r][c] for k in order if L[k][r][c]),0) for c in range(6)] for r in range(3)]
expected_demo=[[2,5,5,5,5,2],[5,5,4,5,5,5],[5,5,0,5,0,0]]
results={}
for tail in permutations([4,2,8]):
 order=(5,)+tail; demo=project(layers_demo,order); test=project(layers_test,order)
 if demo==expected_demo: results[order]=test
print('demo-compatible fixed priority orders and test outputs:')
for order,out in results.items(): print(order,out)
print('unique_outputs',len({str(x) for x in results.values()}))

from hermes_tools import terminal
cmd = "python3 -c 'layers={5:[[5,0,5,0,0,5],[0,5,0,0,0,5],[5,5,5,0,0,0]],4:[[0,0,0,4,0,4],[0,0,0,0,0,0],[4,0,0,4,0,0]],2:[[2,0,2,0,2,2],[2,2,0,2,2,2],[2,2,2,2,2,2]],8:[[0,0,8,8,0,0],[0,8,0,0,8,8],[0,0,0,8,0,0]]}; submitted=[[5,0,5,4,2,5],[2,5,0,2,2,5],[5,5,5,4,2,2]]; order=[5,4,2,8]; out=[]; bad=[]; overlaps=[]; bottom=[];
for r in range(3):
 row=[]; brow=[]
 for c in range(6):
  vals=[layers[k][r][c] for k in order]; nz=[v for v in vals if v]; row.append(next((v for v in vals if v),0)); brow.append(next((v for v in reversed(vals) if v),0));
  if row[-1]!=submitted[r][c]: bad.append((r+1,c+1,vals,row[-1],submitted[r][c]));
  if sum(v!=0 for v in vals)>1: overlaps.append((r+1,c+1,vals,row[-1]));
 out.append(row); bottom.append(brow)
print("direct_topmost=",out); print("exact_submission_match=",out==submitted); print("mismatches=",bad); print("overlapping_cells=",overlaps); print("bottommost_if_stack_order_reversed=",bottom)'"
r=terminal(cmd, timeout=30)
print(r.get('output',''))
print('exit_code',r.get('exit_code'))

